export function sceneBeat(phase){return phase<.16?'Arrive':phase<.32?'Reveal':phase<.84?'Observe':'Depart';}
export function cameraAt(def,phase,reduced=false){const t=reduced?.45:Math.max(0,Math.min(1,phase));const stops=[0,.30,.76,1];let i=0;while(i<2&&t>stops[i+1])i++;let f=(t-stops[i])/(stops[i+1]-stops[i]);f=f*f*(3-2*f);const a=def.shots[i],b=def.shots[i+1];return{position:a.position.map((v,k)=>v+(b.position[k]-v)*f),target:a.target.map((v,k)=>v+(b.target[k]-v)*f)};}
